using Avalonia.Controls;
using Avalonia.Headless;
using Avalonia.Threading;
using Avalonia.VisualTree;
using Stock.Desktop;
internal static partial class Program
{
 private static void DesignCapture()
 {
  var fixture=new MarketFixture{BasePrice=10000,QuoteBase=10611,Design=true};using var services=new AppServices(Path.Combine(output,"isolated-design",Guid.NewGuid().ToString("N")),fixture);using var model=new MainViewModel(services);var window=new MainWindow{DataContext=model,Width=1540,Height=1040,WindowDecorations=WindowDecorations.None};window.Show();model.SearchCommand.Execute(null);Pump(()=>!model.Busy&&model.ChartBars.Length>0);Pump(()=>fixture.CurrentCalls>0);
  Check(window.GetVisualDescendants().OfType<TextBlock>().Any(t=>t.Text==model.PriceText+" 원"),"price header follows the live quote binding after template migration");
  model.ActiveTab=1;Dispatcher.UIThread.RunJobs();var regular=window.GetVisualDescendants().OfType<ScreeningPanel>().Single();var realtime=window.GetVisualDescendants().OfType<RealtimeScreeningPanel>().Single();Check(regular.IsEffectivelyVisible&&!realtime.IsEffectivelyVisible,"normal screening never overlaps the realtime panel");model.ShowRealtimeScreen=true;Dispatcher.UIThread.RunJobs();Check(!regular.IsEffectivelyVisible&&realtime.IsEffectivelyVisible,"realtime mode replaces the normal panel without changing execution lifetime");model.ShowNormalScreen=true;
  var tabs=new[]{"chart","screening","strategy","account","history","market","watch"};
  for(var i=0;i<tabs.Length;i++){model.ActiveTab=i;Dispatcher.UIThread.RunJobs();AvaloniaHeadlessPlatform.ForceRenderTimerTick();using var image=window.CaptureRenderedFrame();image!.Save(Path.Combine(output,"avalonia-"+tabs[i]+".png"),Avalonia.Media.Imaging.PngBitmapEncoderOptions.Default);}
  model.ActiveTab=2;Dispatcher.UIThread.RunJobs();var expanders=window.GetVisualDescendants().OfType<Expander>().ToArray();Check(expanders.Count(e=>e.IsExpanded)==2,"two WPF parameter scopes are expanded by default");var group=expanders.FirstOrDefault(e=>e.Header?.ToString()=="종목 선별 · 급락");Check(group!=null,"semantic WPF parameter groups are present");group!.IsExpanded=true;Dispatcher.UIThread.RunJobs();using(var image=window.CaptureRenderedFrame())image!.Save(Path.Combine(output,"avalonia-parameters.png"),Avalonia.Media.Imaging.PngBitmapEncoderOptions.Default);
  model.ActiveTab=0;Dispatcher.UIThread.RunJobs();var tools=window.GetVisualDescendants().OfType<OrderToolsPanel>().Single();var orderTabs=tools.FindControl<TabControl>("OrderTabs")!;orderTabs.SelectedIndex=2;Dispatcher.UIThread.RunJobs();using(var image=window.CaptureRenderedFrame())image!.Save(Path.Combine(output,"avalonia-backtest.png"),Avalonia.Media.Imaging.PngBitmapEncoderOptions.Default);
  Check(!model.Research.HasResult&&!tools.GetVisualDescendants().OfType<TextBlock>().Any(t=>t.Text=="백테스트 결과"&&t.IsEffectivelyVisible),"no empty backtest result card appears before a run");
  var picker=tools.GetVisualDescendants().OfType<CalendarDatePicker>().First(p=>p.IsEffectivelyVisible);picker.IsDropDownOpen=true;Dispatcher.UIThread.RunJobs();Check(picker.IsDropDownOpen,"restyled calendar still opens its native date selection popup");using(var image=window.CaptureRenderedFrame())image!.Save(Path.Combine(output,"avalonia-calendar.png"),Avalonia.Media.Imaging.PngBitmapEncoderOptions.Default);picker.IsDropDownOpen=false;
  var chart=window.GetVisualDescendants().OfType<StockChart>().Single();model.ShowCloud=true;Dispatcher.UIThread.RunJobs();Check(chart.ShowCloud&&chart.RenderedCandles==model.ChartBars.Length,"Ichimoku display retains every price candle");model.ShowCloud=false;
  foreach(var width in new[]{1160d,1540d}){window.Width=width;Dispatcher.UIThread.RunJobs();Check(chart.Bounds.Width>100&&tools.Bounds.Width>=328,"chart and right tools remain usable at window width "+width);var dateText=tools.GetVisualDescendants().OfType<CalendarDatePicker>().Where(p=>p.IsEffectivelyVisible).SelectMany(p=>p.GetVisualDescendants().OfType<Avalonia.Controls.Presenters.TextPresenter>()).ToArray();Check(dateText.Length==2&&dateText.All(p=>p.Bounds.Width>=p.TextLayout.Width&&p.Bounds.Height>=p.TextLayout.Height),"both backtest dates retain their full text at window width "+width);}
  model.ActiveTab=2;Dispatcher.UIThread.RunJobs();foreach(var expander in window.GetVisualDescendants().OfType<Expander>().ToArray())expander.IsExpanded=true;Dispatcher.UIThread.RunJobs();var inputs=window.GetVisualDescendants().OfType<SettingInput>().Where(c=>c.DataContext is LegacyParameter).ToArray();Check(inputs.Length==61&&inputs.All(c=>c.Content is Control),"all61 original parameter editors are created in their semantic grid cells");Check(inputs.Where(c=>c.DataContext is LegacyParameter{IsText:true}).All(c=>c.Content is TextBox b&&b.Text==((LegacyParameter)c.DataContext!).Text),"every visible numeric/list editor displays the original value without null writes");
  Check(inputs.Select(c=>c.Content).OfType<TextBox>().All(b=>b.Template!=null&&b.Bounds.Height==32),"decimal subclass editors have a real TextBox theme and render at the compact height");
  var account=new AccountDialog{DataContext=model.Accounts};account.Show(window);Dispatcher.UIThread.RunJobs();Check(account.GetVisualDescendants().OfType<Image>().Count(i=>i.Source!=null)==4,"four original broker logos load from embedded portable assets");Check(account.GetVisualDescendants().OfType<SecretInput>().All(b=>b.Template!=null&&b.Bounds.Height>=30),"both credential editors render an actual masked TextBox instead of an empty subclass");model.Accounts.AppKey="DUMMY-KEY";model.Accounts.SelectedInfo=model.Accounts.Brokers.First(b=>b.Id!=model.Accounts.Selected);Dispatcher.UIThread.RunJobs();Check(model.Accounts.AppKey=="","broker tile selection preserves the original credential-clearing guard");using(var image=account.CaptureRenderedFrame())image!.Save(Path.Combine(output,"avalonia-account-dialog.png"),Avalonia.Media.Imaging.PngBitmapEncoderOptions.Default);account.Close();
  window.Close();Console.WriteLine("Design capture complete; fixture data, no broker calls");
 }
}
